## Implementation: User Authentication and Entry Screen

### Overview
This section implements the core authentication flow: user creation, login, profile management, and password reset. The UI uses a modern form with validation, while the backend expects JSON responses and stores sensitive data through secure, encrypted session storage.

### Authentication Service

```typescript
// src/services/auth.service.ts

import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { User } from '../entities/user.entity';
import { JwtService } from '../services/jwt.service';
import { AuthService } from '../auth/auth.service';

@Injectable()
export class AuthService {
  constructor(
    @InjectRepository(User)
    private readonly userRepo: Repository<User>,
    private readonly jwtService: JwtService,
    private readonly authService: AuthService,
  ) {}

  async register(user: Omit<User, 'id'>): Promise<{ message: string; user: User }> {
    const existingUser = await this.userRepo.findOne({ where: { email: user.email } });
    if (existingUser) {
      return { message: 'Email already registered', user: undefined };
    }

    const newUser = await this.userRepo.create({
      ...user,
      passwordHash: this.authService.hashPassword(user.password),
    });

    await this.userRepo.save(newUser);
    return { message: 'Registration successful', user: newUser };
  }

  async login(email: string, password: string): Promise<{ token: string; user: User }> {
    const user = await this.userRepo.findOne({ where: { email } });
    if (!user || !await this.comparePasswords(password, user.passwordHash)) {
      return { token: '', user: undefined };
    }

    const { passwordHash } = user;
    await this.userRepo.delete({ id: user.id });

    const token = this.jwtService.sign({ userId: user.id });

    return { token, user };
  }

  async logout(): Promise<void> {
    await this.userRepo.delete({ id: this.authService.getCurrentUserId() });
  }

  async updateProfile(userId: number, updates: Partial<User>): Promise<User> {
    const existingUser = await this.userRepo.findOne({ where: { id: userId } });
    if (!existingUser) {
      throw new Error('User not found');
    }

    const { passwordHash } = existingUser;

    const updatedUser = await this.userRepo.update({ id: userId }, {
      ...updates,
      passwordHash: passwordHash || this.authService.hashPassword(updates.password),
    });

    return updatedUser;
  }

  async changePassword(userId: number, oldPassword: string, newPassword: string): Promise<User> {
    const user = await this.userRepo.findOne({ where: { id: userId } });
    if (!user || !await this.comparePasswords(oldPassword, user.passwordHash)) {
      throw new Error('Invalid credentials');
    }

    const { passwordHash } = user;
    await this.userRepo.update({ id: userId }, { passwordHash: this.authService.hashPassword(newPassword) });

    return user;
  }

  async forgotPassword(email: string): Promise<User> {
    const user = await this.userRepo.findOne({ where: { email } });
    if (!user) {
      throw new Error('Invalid email');
    }

    return user;
  }

  private async comparePasswords(password: string, hashedPassword: string): Promise<boolean> {
    return password === hashedPassword;
  }

  private getCurrentUserId(): number {
    return this.authService.getTokenUserId();
  }
}
