import { Injectable, UnauthorizedException } from '@nestjs/common';
import { JwtService } from '@nestjs/jwt';
import { AuthService } from './auth.service';
import { UserService } from '../services/user.service';

@Injectable()
export class AuthService {
  constructor(
    private readonly userService: UserService,
    private readonly jwtService: JwtService,
  ) {}

  private async validateToken(token: string): Promise<Record<string, any>> {
    try {
      const payload = await this.jwtService.verifyAsync(token);
      return { id: payload.id, email: payload.email };
    } catch (error) {
      throw new UnauthorizedException('Invalid token');
    }
  }

  private async getTokenUserId(): Promise<number> {
    const token = await this.userService.getTokenFromUser();
    return token ? this.jwtService.getPayload().id : this.userService.getCurrentUserId();
  }

  async login(email: string, password: string): Promise<Record<string, any>> {
    const user = await this.userService.findByEmail(email);
    if (!user) {
      throw new UnauthorizedException('Invalid credentials');
    }

    const { passwordHash } = user;
    if (!await this.userService.comparePasswords(password, passwordHash)) {
      throw new UnauthorizedException('Invalid credentials');
    }

    const token = this.jwtService.sign({ id: user.id, email: user.email });
    return { id: user.id, email: user.email };
  }

  async forgotPassword(email: string): Promise<User> {
    const user = await this.userService.findByEmail(email);
    if (!user) {
      throw new UnauthorizedException('Invalid email');
    }
    return user;
  }

  private async comparePasswords(password: string, passwordHash: string): Promise<boolean> {
    return password === passwordHash;
  }
}
