### Frontend Authentication Logic

```typescript
// src/app/auth.controller.ts

import { Controller, Post, Body, HttpCode, HttpStatus, UseGuards, Req } from '@nestjs/common';
import { AuthService } from '../auth/auth.service';
import { User } from '../entities/user.entity';
import { JwtAuthGuard } from '../guards/jwt-auth.guard';

@Controller('auth')
@UseGuards(JwtAuthGuard)
export class AuthController {
  constructor(private readonly authService: AuthService) {}

  @Post('register')
  @HttpCode(HttpStatus.CREATED)
  async register(@Body() user: User) {
    return this.authService.register(user);
  }

  @Post('login')
  @HttpCode(HttpStatus.OK)
  async login(@Body() credentials: { email: string; password: string }) {
    const { id, email } = await this.authService.login(credentials.email, credentials.password);
    return { id, email };
  }

  @Post('logout')
  @HttpCode(HttpStatus.OK)
  async logout() {
    await this.authService.logout();
    return { success: true };
  }

  @Post('update-profile')
  @HttpCode(HttpStatus.OK)
  async updateProfile(@Body() updates: Partial<User>) {
    return this.authService.updateProfile(this.authService.getCurrentUserId(), updates);
  }

  @Post('change-password')
  @HttpCode(HttpStatus.OK)
  async changePassword(@Body() updates: { oldPassword: string; password: string }) {
    return this.authService.changePassword(this.authService.getCurrentUserId(), updates.oldPassword, updates.password);
  }

  @Post('forgot-password')
  @HttpCode(HttpStatus.OK)
  async forgotPassword(@Body() email: string) {
    return this.authService.forgotPassword(email);
  }
}
